1	package posemap
2	
3	import (
4		"math"
5		"path/filepath"
6		"testing"
7	)
8	
9	// 微小转角（1e-16 弧度）是有限且可表示的真实运动，更新朝向时不能被当成
10	// 舍入误差丢掉：要逐帧累积、保留正负号、零增量不把已有小朝向清零，并且
11	// 实际参与后续定位（自身坐标平移按运动前朝向转换、路标观测按运动完成后
12	// 朝向转换），持久化重开后仍保持。回环校正沿用同一角度含义，角度始终
13	// 归一到 [-π,π)，正 π 表示为负 π。
14	const tinyHeading = 1e-16
15	
16	// normalizeAngle 单元层面的不变量：范围内可表示的小角度原样保留，零保持
17	// 零，+π 折回 -π，略小于 -π 的可表示输入也折回 [-π,π) 而不会输出 +π。
18	func TestNormalizeAnglePreservesTiny(t *testing.T) {
19		cases := []struct {
20			name string
21			in   float64
22			want float64
23		}{
24			{"tiny positive", tinyHeading, tinyHeading},
25			{"tiny negative", -tinyHeading, -tinyHeading},
26			{"zero", 0, 0},
27			{"plus pi", math.Pi, -math.Pi},
28			{"minus pi", -math.Pi, -math.Pi},
29			{"just below minus pi folds past plus pi", -math.Pi - math.Pi*math.Ldexp(1, -52), normalizeAngle(math.Pi - math.Pi*math.Ldexp(1, -52))},
30		}
31		for _, tc := range cases {
32			t.Run(tc.name, func(t *testing.T) {
33				got := normalizeAngle(tc.in)
34				if got != tc.want {
35					t.Fatalf("normalizeAngle(%v) = %v, want %v", tc.in, got, tc.want)
36				}
37				if got >= math.Pi || got < -math.Pi {
38					t.Fatalf("normalizeAngle(%v) = %v outside [-pi,pi)", tc.in, got)
39				}
40			})
41		}
42	}
43	
44	// 连续三帧各增加一个微小正转角：第三帧朝向按正常浮点加法累积到约 3e-16；
45	// 负增量累积到对应负方向。
46	func TestTinyHeadingAccumulates(t *testing.T) {
47		cases := []struct {
48			name string
49			step float64
50			want float64
51		}{
52			{"positive", tinyHeading, 3e-16},
53			{"negative", -tinyHeading, -3e-16},
54		}
55		for _, tc := range cases {
56			t.Run(tc.name, func(t *testing.T) {
57				m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
58				frames := make([]Frame, 3)
59				for i := range frames {
60					frames[i] = Frame{Time: int64(10 * (i + 1)), DHeading: tc.step}
61				}
62				res, err := m.ImportSegment(Segment{ID: "s", Frames: frames})
63				if err != nil {
64					t.Fatalf("ImportSegment: %v", err)
65				}
66				if res.EndPose.Heading != tc.want {
67					t.Fatalf("segment end heading = %v, want %v", res.EndPose.Heading, tc.want)
68				}
69				// 每一帧的历史位姿都应保留累积到当时的朝向。
70				for i := range frames {
71					got, err := m.PoseAt(frames[i].Time)
72					if err != nil {
73						t.Fatalf("PoseAt(%d): %v", frames[i].Time, err)
74					}
75					want := float64(i+1) * tc.step
76					if got.Heading != want {
77						t.Fatalf("PoseAt(%d) heading = %v, want %v", frames[i].Time, got.Heading, want)
78					}
79				}
80				cur, _ := m.CurrentPose()
81				if cur.Heading != tc.want {
82					t.Fatalf("current heading = %v, want %v", cur.Heading, tc.want)
83				}
84			})
85		}
86	}
87	
88	// 已有一个小朝向时，下一帧朝向增量为零必须保持原朝向，不能经过一次更新
89	// 就被清零。
90	func TestTinyHeadingSurvivesZeroIncrement(t *testing.T) {
91		m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
92		res, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
93			{Time: 10, DHeading: tinyHeading},
94			{Time: 20, DHeading: 0},
95		}})
96		if err != nil {
97			t.Fatalf("ImportSegment: %v", err)
98		}
99		if res.EndPose.Heading != tinyHeading {
100			t.Fatalf("heading after zero increment = %v, want %v", res.EndPose.Heading, tinyHeading)
101		}
102	}
103	
104	// 小朝向必须实际参与定位：转向后的下一次前进按运动前朝向旋转，留下与该
105	// 方向一致的横向分量；转向帧中的路标观测按运动完成后的朝向转换，位置也
106	// 带同一横向分量。
107	func TestTinyHeadingDrivesKinematicsAndObservations(t *testing.T) {
108		dir := t.TempDir()
109		path := filepath.Join(dir, "map.pose")
110		m, err := Create(path, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
111		if err != nil {
112			t.Fatalf("Create: %v", err)
113		}
114		// 第 1 帧：原地转向 1e-16，运动完成后在自身坐标正前方 (1,0) 观测路标 L。
115		// 第 2 帧：朝向增量 0，自身坐标前进 1（按运动前朝向 1e-16 转换）。
116		// 第 3 帧：朝向增量 0，朝向继续保持。
117		res, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
118			{Time: 10, DHeading: tinyHeading, Observations: []Observation{{ID: "L", X: 1, Y: 0}}},
119			{Time: 20, DX: 1, DHeading: 0},
120			{Time: 30, DHeading: 0},
121		}})
122		if err != nil {
123			t.Fatalf("ImportSegment: %v", err)
124		}
125		wantX := math.Cos(tinyHeading)
126		wantY := math.Sin(tinyHeading)
127		if wantY == 0 {
128			t.Fatalf("test setup: sin(%v) rounded to zero", tinyHeading)
129		}
130		// 前进与路标观测都必须带上与小朝向一致的横向分量。
131		if res.EndPose.X != wantX || res.EndPose.Y != wantY {
132			t.Fatalf("end pose = (%v,%v), want (%v,%v)", res.EndPose.X, res.EndPose.Y, wantX, wantY)
133		}
134		if res.EndPose.Heading != tinyHeading {
135			t.Fatalf("end heading = %v, want %v", res.EndPose.Heading, tinyHeading)
136		}
137		for _, tm := range []int64{10, 20, 30} {
138			p, err := m.PoseAt(tm)
139			if err != nil {
140				t.Fatalf("PoseAt(%d): %v", tm, err)
141			}
142			if p.Heading != tinyHeading {
143				t.Fatalf("PoseAt(%d) heading = %v, want %v", tm, p.Heading, tinyHeading)
144			}
145		}
146		cur, _ := m.CurrentPose()
147		if cur.Heading != tinyHeading || cur.X != wantX || cur.Y != wantY {
148			t.Fatalf("current pose = %+v, want (%v,%v,%v)", cur, wantX, wantY, tinyHeading)
149		}
150		lms, err := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
151		if err != nil {
152			t.Fatal(err)
153		}
154		if len(lms) != 1 || lms[0].ID != "L" || lms[0].Count != 1 {
155			t.Fatalf("landmarks = %+v", lms)
156		}
157		if lms[0].X != wantX || lms[0].Y != wantY {
158			t.Fatalf("landmark = (%v,%v), want (%v,%v): lateral component lost", lms[0].X, lms[0].Y, wantX, wantY)
159		}
160	
161		// 落盘后重开：小朝向与其定位结果保持一致，不在打开时再次被清零。
162		if err := m.Close(); err != nil {
163			t.Fatal(err)
164		}
165		m2, err := Open(path)
166		if err != nil {
167			t.Fatalf("Open: %v", err)
168		}
169		defer m2.Close()
170		cur, _ = m2.CurrentPose()
171		if cur.Heading != tinyHeading || cur.X != wantX || cur.Y != wantY {
172			t.Fatalf("after reopen current pose = %+v, want (%v,%v,%v)", cur, wantX, wantY, tinyHeading)
173		}
174		for _, tm := range []int64{10, 20, 30} {
175			p, err := m2.PoseAt(tm)
176			if err != nil {
177				t.Fatalf("reopen PoseAt(%d): %v", tm, err)
178			}
179			if p.Heading != tinyHeading {
180				t.Fatalf("reopen PoseAt(%d) heading = %v, want %v", tm, p.Heading, tinyHeading)
181			}
182		}
183		lms, _ = m2.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
184		if len(lms) != 1 || lms[0].X != wantX || lms[0].Y != wantY {
185			t.Fatalf("after reopen landmark = %+v, want (%v,%v)", lms, wantX, wantY)
186		}
187	}
188	
189	// 回环校正：锚点原朝向为零、目标位置不变而目标朝向为 1e-16。锚点与后续
190	// 轨迹必须包含这次转向，受影响路标观测随之更新；不能把它误判为几何与
191	// 朝向完全不变的恒等校正。校正记录中的前后值如实反映结果，重开后一致。
192	func TestTinyHeadingLoopCorrection(t *testing.T) {
193		m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
194		// 锚点帧 t=10 前进到 (1,0)；末帧 t=20 再前进到 (2,0)，在自身正前方
195		// (1,0) 观测 L，地图坐标 (3,0)。
196		if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
197			{Time: 10, DX: 1},
198			{Time: 20, DX: 1, Observations: []Observation{{ID: "L", X: 1, Y: 0}}},
199		}}); err != nil {
200			t.Fatalf("ImportSegment: %v", err)
201		}
202		rec, err := m.Correct(Correction{
203			ID:     "c",
204			Anchor: 10,
205			Target: CorrectionTarget{X: 1, Y: 0, Heading: tinyHeading, Variance: 0},
206		})
207		if err != nil {
208			t.Fatalf("Correct: %v", err)
209		}
210		if len(rec.Poses) != 2 {
211			t.Fatalf("pose changes = %d, want 2", len(rec.Poses))
212		}
213		// 锚点：位置不变，朝向从零变为 1e-16——不是恒等校正。
214		if rec.Poses[0].Before.Heading != 0 || rec.Poses[0].After.Heading != tinyHeading {
215			t.Fatalf("anchor heading %v -> %v, want 0 -> %v", rec.Poses[0].Before.Heading, rec.Poses[0].After.Heading, tinyHeading)
216		}
217		if rec.Poses[0].After.X != 1 || rec.Poses[0].After.Y != 0 {
218			t.Fatalf("anchor after = (%v,%v), want (1,0)", rec.Poses[0].After.X, rec.Poses[0].After.Y)
219		}
220		// 后续帧随锚点一起旋转：(2,0) -> (2, sin(1e-16))，保留横向分量。
221		wantY := math.Sin(tinyHeading)
222		if rec.Poses[1].Before.X != 2 || rec.Poses[1].Before.Y != 0 || rec.Poses[1].Before.Heading != 0 {
223			t.Fatalf("tail before = %+v, want (2,0,0)", rec.Poses[1].Before)
224		}
225		if rec.Poses[1].After.X != 2 || rec.Poses[1].After.Y != wantY || rec.Poses[1].After.Heading != tinyHeading {
226			t.Fatalf("tail after = %+v, want (2,%v,%v)", rec.Poses[1].After, wantY, tinyHeading)
227		}
228		// 受影响路标观测按校正后位姿重放：(3,0) -> (3, 2*sin(1e-16))。
229		if len(rec.Landmarks) != 1 || rec.Landmarks[0].ID != "L" {
230			t.Fatalf("landmark changes = %+v", rec.Landmarks)
231		}
232		lc := rec.Landmarks[0]
233		if lc.Before.X != 3 || lc.Before.Y != 0 || lc.After.X != 3 || lc.After.Y != 2*wantY {
234			t.Fatalf("landmark change = (%v,%v) -> (%v,%v), want (3,0) -> (3,%v)",
235				lc.Before.X, lc.Before.Y, lc.After.X, lc.After.Y, 2*wantY)
236		}
237		// 当前位姿实际采用校正后朝向。
238		cur, _ := m.CurrentPose()
239		if cur.Heading != tinyHeading || cur.X != 2 || cur.Y != wantY {
240			t.Fatalf("current pose = %+v, want (2,%v,%v)", cur, wantY, tinyHeading)
241		}
242	
243		// 重开后当前位姿、路标与校正记录保持一致，打开核对不把微小转向当作
244		// 几何矛盾，也不重新清零。
245		path := m.Path()
246		if err := m.Close(); err != nil {
247			t.Fatal(err)
248		}
249		m2, err := Open(path)
250		if err != nil {
251			t.Fatalf("Open: %v", err)
252		}
253		defer m2.Close()
254		cur, _ = m2.CurrentPose()
255		if cur.Heading != tinyHeading || cur.X != 2 || cur.Y != wantY {
256			t.Fatalf("after reopen current pose = %+v, want (2,%v,%v)", cur, wantY, tinyHeading)
257		}
258		lms, _ := m2.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
259		if len(lms) != 1 || lms[0].X != 3 || lms[0].Y != 2*wantY {
260			t.Fatalf("after reopen landmark = %+v, want (3,%v)", lms, 2*wantY)
261		}
262		recs, err := m2.Corrections()
263		if err != nil {
264			t.Fatal(err)
265		}
266		if len(recs) != 1 || len(recs[0].Poses) != 2 ||
267			recs[0].Poses[0].After.Heading != tinyHeading ||
268			recs[0].Poses[1].After.Y != wantY {
269			t.Fatalf("after reopen correction record = %+v", recs)
270		}
271	}
272	
273	// 回环校正：锚点朝向为 1 弧度、目标朝向为 ±1e-20 弧度——目标远小于锚点
274	// 朝向，但它是有限且可表示的非零角度，必须作为实际定位结果保留，不能在
275	// 计算旋转角时被锚点朝向的精度吞掉而退化为零。锚点及原本与锚点朝向相同
276	// 的帧都得到该目标朝向；有其他朝向差的帧保留相对方向；受影响路标观测的
277	// 地图纵坐标保留约 1e-20 的非零分量（负目标时为负）；校正后的末帧朝向继
278	// 续驱动随后导入的运动；重开后结果一致。
279	func TestTinyTargetHeadingSurvivesLargeAnchorHeading(t *testing.T) {
280		for _, target := range []float64{1e-20, -1e-20} {
281			name := "positive"
282			if target < 0 {
283				name = "negative"
284			}
285			t.Run(name, func(t *testing.T) {
286				m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
287				// t=10 锚点：原地转向 1 弧度（位置保持原点）。t=20 再转 0.5，
288				// t=30 转回 -0.5（与锚点朝向同为 1）并在自身正前方 (1,0) 观测 L。
289				if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
290					{Time: 10, DHeading: 1},
291					{Time: 20, DHeading: 0.5},
292					{Time: 30, DHeading: -0.5, Observations: []Observation{{ID: "L", X: 1, Y: 0}}},
293				}}); err != nil {
294					t.Fatalf("ImportSegment: %v", err)
295				}
296				rec, err := m.Correct(Correction{
297					ID:     "c",
298					Anchor: 10,
299					Target: CorrectionTarget{X: 0, Y: 0, Heading: target, Variance: 0},
300				})
301				if err != nil {
302					t.Fatalf("Correct: %v", err)
303				}
304				if len(rec.Poses) != 3 {
305					t.Fatalf("pose changes = %d, want 3", len(rec.Poses))
306				}
307				// 锚点：朝向从 1 变为目标小角度本身，不是零。
308				if rec.Poses[0].Before.Heading != 1 || rec.Poses[0].After.Heading != target {
309					t.Fatalf("anchor heading %v -> %v, want 1 -> %v", rec.Poses[0].Before.Heading, rec.Poses[0].After.Heading, target)
310				}
311				// 与锚点朝向差 +0.5 的帧保留相对方向。
312				want20 := normalizeAngle(target + 0.5)
313				if rec.Poses[1].After.Heading != want20 {
314					t.Fatalf("frame 20 heading = %v, want %v", rec.Poses[1].After.Heading, want20)
315				}
316				// 原本与锚点朝向完全相同的末帧得到同一目标朝向。
317				if rec.Poses[2].Before.Heading != 1 || rec.Poses[2].After.Heading != target {
318					t.Fatalf("frame 30 heading %v -> %v, want 1 -> %v", rec.Poses[2].Before.Heading, rec.Poses[2].After.Heading, target)
319				}
320				// 历史查询与当前位姿都反映实际校正结果。
321				for _, tm := range []int64{10, 30} {
322					p, err := m.PoseAt(tm)
323					if err != nil {
324						t.Fatalf("PoseAt(%d): %v", tm, err)
325					}
326					if p.Heading != target {
327						t.Fatalf("PoseAt(%d) heading = %v, want %v", tm, p.Heading, target)
328					}
329				}
330				if p, _ := m.PoseAt(20); p.Heading != want20 {
331					t.Fatalf("PoseAt(20) heading = %v, want %v", p.Heading, want20)
332				}
333				if cur, _ := m.CurrentPose(); cur.Heading != target {
334					t.Fatalf("current heading = %v, want %v", cur.Heading, target)
335				}
336				// 路标观测按保留的小朝向转换：正前方 1 米的路标地图纵坐标保留
337				// 与目标同号的非零分量（sin(±1e-20) 在 float64 中即 ±1e-20）。
338				if len(rec.Landmarks) != 1 || rec.Landmarks[0].ID != "L" {
339					t.Fatalf("landmark changes = %+v", rec.Landmarks)
340				}
341				if la := rec.Landmarks[0].After; la.X != 1 || la.Y != target {
342					t.Fatalf("landmark after = (%v,%v), want (1,%v)", la.X, la.Y, target)
343				}
344				lms, err := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
345				if err != nil {
346					t.Fatal(err)
347				}
348				if len(lms) != 1 || lms[0].X != 1 || lms[0].Y != target {
349					t.Fatalf("landmarks = %+v, want (1,%v)", lms, target)
350				}
351				// 校正后的末帧带有小朝向：随后导入的前进运动按它定位，留下同
352				// 号的横向分量，而不是重新按零朝向定位。
353				res, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
354					{Time: 40, DX: 1, DHeading: 0},
355				}})
356				if err != nil {
357					t.Fatalf("ImportSegment after correction: %v", err)
358				}
359				if res.EndPose.Heading != target || res.EndPose.X != 1 || res.EndPose.Y != target {
360					t.Fatalf("end pose = (%v,%v,%v), want (1,%v,%v)",
361						res.EndPose.X, res.EndPose.Y, res.EndPose.Heading, target, target)
362				}
363	
364				// 重开后当前位姿、历史查询、路标与校正记录保持一致。
365				path := m.Path()
366				if err := m.Close(); err != nil {
367					t.Fatal(err)
368				}
369				m2, err := Open(path)
370				if err != nil {
371					t.Fatalf("Open: %v", err)
372				}
373				defer m2.Close()
374				if cur, _ := m2.CurrentPose(); cur.Heading != target || cur.X != 1 || cur.Y != target {
375					t.Fatalf("after reopen current pose = %+v, want (1,%v,%v)", cur, target, target)
376				}
377				if p, _ := m2.PoseAt(10); p.Heading != target {
378					t.Fatalf("after reopen PoseAt(10) heading = %v, want %v", p.Heading, target)
379				}
380				lms, _ = m2.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
381				if len(lms) != 1 || lms[0].X != 1 || lms[0].Y != target {
382					t.Fatalf("after reopen landmark = %+v, want (1,%v)", lms, target)
383				}
384				recs, err := m2.Corrections()
385				if err != nil {
386					t.Fatal(err)
387				}
388				if len(recs) != 1 || len(recs[0].Poses) != 3 ||
389					recs[0].Poses[0].After.Heading != target ||
390					recs[0].Poses[2].After.Heading != target {
391					t.Fatalf("after reopen correction record = %+v", recs)
392				}
393			})
394		}
395	}
396	
397	// 跨越 ±π 边界的校正仍表示同一个物理方向：锚点朝向在 +π 附近，目标再向
398	// 正方向越过 +π，结果归一为 -π 一侧的等价角度，锚点位置不变。
399	func TestTinyHeadingCorrectionAcrossPiBoundary(t *testing.T) {
400		m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
401		anchorHeading := normalizeAngle(math.Pi - 1e-15) // +π 内侧一个可表示的小角
402		if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
403			{Time: 10, DHeading: anchorHeading},
404		}}); err != nil {
405			t.Fatalf("ImportSegment: %v", err)
406		}
407		// 目标朝向沿正方向再转 3e-15，物理上越过 +π；提交值本身在范围外，
408		// 由校正归一。
409		targetHeading := anchorHeading + 3e-15
410		rec, err := m.Correct(Correction{
411			ID:     "c",
412			Anchor: 10,
413			Target: CorrectionTarget{X: 0, Y: 0, Heading: targetHeading, Variance: 0},
414		})
415		if err != nil {
416			t.Fatalf("Correct: %v", err)
417		}
418		dHeading := normalizeAngle(normalizeAngle(targetHeading) - anchorHeading)
419		want := normalizeAngle(anchorHeading + dHeading)
420		if want >= 0 {
421			t.Fatalf("test setup: expected wrap to the -pi side, got %v", want)
422		}
423		if rec.Poses[0].After.Heading != want {
424			t.Fatalf("corrected heading = %v, want boundary-folded %v", rec.Poses[0].After.Heading, want)
425		}
426		if rec.Poses[0].After.X != 0 || rec.Poses[0].After.Y != 0 {
427			t.Fatalf("anchor position changed: (%v,%v)", rec.Poses[0].After.X, rec.Poses[0].After.Y)
428		}
429		// 正 π 始终表示为负 π。
430		if h := rec.Poses[0].After.Heading; h >= math.Pi || h < -math.Pi {
431			t.Fatalf("heading %v outside [-pi, pi)", h)
432		}
433	}
434

