package posemap

import (
	"math"
	"path/filepath"
	"testing"
)

// 微小转角（1e-16 弧度）是有限且可表示的真实运动，更新朝向时不能被当成
// 舍入误差丢掉：要逐帧累积、保留正负号、零增量不把已有小朝向清零，并且
// 实际参与后续定位（自身坐标平移按运动前朝向转换、路标观测按运动完成后
// 朝向转换），持久化重开后仍保持。回环校正沿用同一角度含义，角度始终
// 归一到 [-π,π)，正 π 表示为负 π。
const tinyHeading = 1e-16

// normalizeAngle 单元层面的不变量：范围内可表示的小角度原样保留，零保持
// 零，+π 折回 -π，略小于 -π 的可表示输入也折回 [-π,π) 而不会输出 +π。
func TestNormalizeAnglePreservesTiny(t *testing.T) {
	cases := []struct {
		name string
		in   float64
		want float64
	}{
		{"tiny positive", tinyHeading, tinyHeading},
		{"tiny negative", -tinyHeading, -tinyHeading},
		{"zero", 0, 0},
		{"plus pi", math.Pi, -math.Pi},
		{"minus pi", -math.Pi, -math.Pi},
		{"just below minus pi folds past plus pi", -math.Pi - math.Pi*math.Ldexp(1, -52), normalizeAngle(math.Pi - math.Pi*math.Ldexp(1, -52))},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := normalizeAngle(tc.in)
			if got != tc.want {
				t.Fatalf("normalizeAngle(%v) = %v, want %v", tc.in, got, tc.want)
			}
			if got >= math.Pi || got < -math.Pi {
				t.Fatalf("normalizeAngle(%v) = %v outside [-pi,pi)", tc.in, got)
			}
		})
	}
}

// 连续三帧各增加一个微小正转角：第三帧朝向按正常浮点加法累积到约 3e-16；
// 负增量累积到对应负方向。
func TestTinyHeadingAccumulates(t *testing.T) {
	cases := []struct {
		name string
		step float64
		want float64
	}{
		{"positive", tinyHeading, 3e-16},
		{"negative", -tinyHeading, -3e-16},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
			frames := make([]Frame, 3)
			for i := range frames {
				frames[i] = Frame{Time: int64(10 * (i + 1)), DHeading: tc.step}
			}
			res, err := m.ImportSegment(Segment{ID: "s", Frames: frames})
			if err != nil {
				t.Fatalf("ImportSegment: %v", err)
			}
			if res.EndPose.Heading != tc.want {
				t.Fatalf("segment end heading = %v, want %v", res.EndPose.Heading, tc.want)
			}
			// 每一帧的历史位姿都应保留累积到当时的朝向。
			for i := range frames {
				got, err := m.PoseAt(frames[i].Time)
				if err != nil {
					t.Fatalf("PoseAt(%d): %v", frames[i].Time, err)
				}
				want := float64(i+1) * tc.step
				if got.Heading != want {
					t.Fatalf("PoseAt(%d) heading = %v, want %v", frames[i].Time, got.Heading, want)
				}
			}
			cur, _ := m.CurrentPose()
			if cur.Heading != tc.want {
				t.Fatalf("current heading = %v, want %v", cur.Heading, tc.want)
			}
		})
	}
}

// 已有一个小朝向时，下一帧朝向增量为零必须保持原朝向，不能经过一次更新
// 就被清零。
func TestTinyHeadingSurvivesZeroIncrement(t *testing.T) {
	m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
	res, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
		{Time: 10, DHeading: tinyHeading},
		{Time: 20, DHeading: 0},
	}})
	if err != nil {
		t.Fatalf("ImportSegment: %v", err)
	}
	if res.EndPose.Heading != tinyHeading {
		t.Fatalf("heading after zero increment = %v, want %v", res.EndPose.Heading, tinyHeading)
	}
}

// 小朝向必须实际参与定位：转向后的下一次前进按运动前朝向旋转，留下与该
// 方向一致的横向分量；转向帧中的路标观测按运动完成后的朝向转换，位置也
// 带同一横向分量。
func TestTinyHeadingDrivesKinematicsAndObservations(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "map.pose")
	m, err := Create(path, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	// 第 1 帧：原地转向 1e-16，运动完成后在自身坐标正前方 (1,0) 观测路标 L。
	// 第 2 帧：朝向增量 0，自身坐标前进 1（按运动前朝向 1e-16 转换）。
	// 第 3 帧：朝向增量 0，朝向继续保持。
	res, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
		{Time: 10, DHeading: tinyHeading, Observations: []Observation{{ID: "L", X: 1, Y: 0}}},
		{Time: 20, DX: 1, DHeading: 0},
		{Time: 30, DHeading: 0},
	}})
	if err != nil {
		t.Fatalf("ImportSegment: %v", err)
	}
	wantX := math.Cos(tinyHeading)
	wantY := math.Sin(tinyHeading)
	if wantY == 0 {
		t.Fatalf("test setup: sin(%v) rounded to zero", tinyHeading)
	}
	// 前进与路标观测都必须带上与小朝向一致的横向分量。
	if res.EndPose.X != wantX || res.EndPose.Y != wantY {
		t.Fatalf("end pose = (%v,%v), want (%v,%v)", res.EndPose.X, res.EndPose.Y, wantX, wantY)
	}
	if res.EndPose.Heading != tinyHeading {
		t.Fatalf("end heading = %v, want %v", res.EndPose.Heading, tinyHeading)
	}
	for _, tm := range []int64{10, 20, 30} {
		p, err := m.PoseAt(tm)
		if err != nil {
			t.Fatalf("PoseAt(%d): %v", tm, err)
		}
		if p.Heading != tinyHeading {
			t.Fatalf("PoseAt(%d) heading = %v, want %v", tm, p.Heading, tinyHeading)
		}
	}
	cur, _ := m.CurrentPose()
	if cur.Heading != tinyHeading || cur.X != wantX || cur.Y != wantY {
		t.Fatalf("current pose = %+v, want (%v,%v,%v)", cur, wantX, wantY, tinyHeading)
	}
	lms, err := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
	if err != nil {
		t.Fatal(err)
	}
	if len(lms) != 1 || lms[0].ID != "L" || lms[0].Count != 1 {
		t.Fatalf("landmarks = %+v", lms)
	}
	if lms[0].X != wantX || lms[0].Y != wantY {
		t.Fatalf("landmark = (%v,%v), want (%v,%v): lateral component lost", lms[0].X, lms[0].Y, wantX, wantY)
	}

	// 落盘后重开：小朝向与其定位结果保持一致，不在打开时再次被清零。
	if err := m.Close(); err != nil {
		t.Fatal(err)
	}
	m2, err := Open(path)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer m2.Close()
	cur, _ = m2.CurrentPose()
	if cur.Heading != tinyHeading || cur.X != wantX || cur.Y != wantY {
		t.Fatalf("after reopen current pose = %+v, want (%v,%v,%v)", cur, wantX, wantY, tinyHeading)
	}
	for _, tm := range []int64{10, 20, 30} {
		p, err := m2.PoseAt(tm)
		if err != nil {
			t.Fatalf("reopen PoseAt(%d): %v", tm, err)
		}
		if p.Heading != tinyHeading {
			t.Fatalf("reopen PoseAt(%d) heading = %v, want %v", tm, p.Heading, tinyHeading)
		}
	}
	lms, _ = m2.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
	if len(lms) != 1 || lms[0].X != wantX || lms[0].Y != wantY {
		t.Fatalf("after reopen landmark = %+v, want (%v,%v)", lms, wantX, wantY)
	}
}

// 回环校正：锚点原朝向为零、目标位置不变而目标朝向为 1e-16。锚点与后续
// 轨迹必须包含这次转向，受影响路标观测随之更新；不能把它误判为几何与
// 朝向完全不变的恒等校正。校正记录中的前后值如实反映结果，重开后一致。
func TestTinyHeadingLoopCorrection(t *testing.T) {
	m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
	// 锚点帧 t=10 前进到 (1,0)；末帧 t=20 再前进到 (2,0)，在自身正前方
	// (1,0) 观测 L，地图坐标 (3,0)。
	if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
		{Time: 10, DX: 1},
		{Time: 20, DX: 1, Observations: []Observation{{ID: "L", X: 1, Y: 0}}},
	}}); err != nil {
		t.Fatalf("ImportSegment: %v", err)
	}
	rec, err := m.Correct(Correction{
		ID:     "c",
		Anchor: 10,
		Target: CorrectionTarget{X: 1, Y: 0, Heading: tinyHeading, Variance: 0},
	})
	if err != nil {
		t.Fatalf("Correct: %v", err)
	}
	if len(rec.Poses) != 2 {
		t.Fatalf("pose changes = %d, want 2", len(rec.Poses))
	}
	// 锚点：位置不变，朝向从零变为 1e-16——不是恒等校正。
	if rec.Poses[0].Before.Heading != 0 || rec.Poses[0].After.Heading != tinyHeading {
		t.Fatalf("anchor heading %v -> %v, want 0 -> %v", rec.Poses[0].Before.Heading, rec.Poses[0].After.Heading, tinyHeading)
	}
	if rec.Poses[0].After.X != 1 || rec.Poses[0].After.Y != 0 {
		t.Fatalf("anchor after = (%v,%v), want (1,0)", rec.Poses[0].After.X, rec.Poses[0].After.Y)
	}
	// 后续帧随锚点一起旋转：(2,0) -> (2, sin(1e-16))，保留横向分量。
	wantY := math.Sin(tinyHeading)
	if rec.Poses[1].Before.X != 2 || rec.Poses[1].Before.Y != 0 || rec.Poses[1].Before.Heading != 0 {
		t.Fatalf("tail before = %+v, want (2,0,0)", rec.Poses[1].Before)
	}
	if rec.Poses[1].After.X != 2 || rec.Poses[1].After.Y != wantY || rec.Poses[1].After.Heading != tinyHeading {
		t.Fatalf("tail after = %+v, want (2,%v,%v)", rec.Poses[1].After, wantY, tinyHeading)
	}
	// 受影响路标观测按校正后位姿重放：(3,0) -> (3, 2*sin(1e-16))。
	if len(rec.Landmarks) != 1 || rec.Landmarks[0].ID != "L" {
		t.Fatalf("landmark changes = %+v", rec.Landmarks)
	}
	lc := rec.Landmarks[0]
	if lc.Before.X != 3 || lc.Before.Y != 0 || lc.After.X != 3 || lc.After.Y != 2*wantY {
		t.Fatalf("landmark change = (%v,%v) -> (%v,%v), want (3,0) -> (3,%v)",
			lc.Before.X, lc.Before.Y, lc.After.X, lc.After.Y, 2*wantY)
	}
	// 当前位姿实际采用校正后朝向。
	cur, _ := m.CurrentPose()
	if cur.Heading != tinyHeading || cur.X != 2 || cur.Y != wantY {
		t.Fatalf("current pose = %+v, want (2,%v,%v)", cur, wantY, tinyHeading)
	}

	// 重开后当前位姿、路标与校正记录保持一致，打开核对不把微小转向当作
	// 几何矛盾，也不重新清零。
	path := m.Path()
	if err := m.Close(); err != nil {
		t.Fatal(err)
	}
	m2, err := Open(path)
	if err != nil {
		t.Fatalf("Open: %v", err)
	}
	defer m2.Close()
	cur, _ = m2.CurrentPose()
	if cur.Heading != tinyHeading || cur.X != 2 || cur.Y != wantY {
		t.Fatalf("after reopen current pose = %+v, want (2,%v,%v)", cur, wantY, tinyHeading)
	}
	lms, _ := m2.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
	if len(lms) != 1 || lms[0].X != 3 || lms[0].Y != 2*wantY {
		t.Fatalf("after reopen landmark = %+v, want (3,%v)", lms, 2*wantY)
	}
	recs, err := m2.Corrections()
	if err != nil {
		t.Fatal(err)
	}
	if len(recs) != 1 || len(recs[0].Poses) != 2 ||
		recs[0].Poses[0].After.Heading != tinyHeading ||
		recs[0].Poses[1].After.Y != wantY {
		t.Fatalf("after reopen correction record = %+v", recs)
	}
}

// 回环校正：锚点朝向为 1 弧度、目标朝向为 ±1e-20 弧度——目标远小于锚点
// 朝向，但它是有限且可表示的非零角度，必须作为实际定位结果保留，不能在
// 计算旋转角时被锚点朝向的精度吞掉而退化为零。锚点及原本与锚点朝向相同
// 的帧都得到该目标朝向；有其他朝向差的帧保留相对方向；受影响路标观测的
// 地图纵坐标保留约 1e-20 的非零分量（负目标时为负）；校正后的末帧朝向继
// 续驱动随后导入的运动；重开后结果一致。
func TestTinyTargetHeadingSurvivesLargeAnchorHeading(t *testing.T) {
	for _, target := range []float64{1e-20, -1e-20} {
		name := "positive"
		if target < 0 {
			name = "negative"
		}
		t.Run(name, func(t *testing.T) {
			m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
			// t=10 锚点：原地转向 1 弧度（位置保持原点）。t=20 再转 0.5，
			// t=30 转回 -0.5（与锚点朝向同为 1）并在自身正前方 (1,0) 观测 L。
			if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
				{Time: 10, DHeading: 1},
				{Time: 20, DHeading: 0.5},
				{Time: 30, DHeading: -0.5, Observations: []Observation{{ID: "L", X: 1, Y: 0}}},
			}}); err != nil {
				t.Fatalf("ImportSegment: %v", err)
			}
			rec, err := m.Correct(Correction{
				ID:     "c",
				Anchor: 10,
				Target: CorrectionTarget{X: 0, Y: 0, Heading: target, Variance: 0},
			})
			if err != nil {
				t.Fatalf("Correct: %v", err)
			}
			if len(rec.Poses) != 3 {
				t.Fatalf("pose changes = %d, want 3", len(rec.Poses))
			}
			// 锚点：朝向从 1 变为目标小角度本身，不是零。
			if rec.Poses[0].Before.Heading != 1 || rec.Poses[0].After.Heading != target {
				t.Fatalf("anchor heading %v -> %v, want 1 -> %v", rec.Poses[0].Before.Heading, rec.Poses[0].After.Heading, target)
			}
			// 与锚点朝向差 +0.5 的帧保留相对方向。
			want20 := normalizeAngle(target + 0.5)
			if rec.Poses[1].After.Heading != want20 {
				t.Fatalf("frame 20 heading = %v, want %v", rec.Poses[1].After.Heading, want20)
			}
			// 原本与锚点朝向完全相同的末帧得到同一目标朝向。
			if rec.Poses[2].Before.Heading != 1 || rec.Poses[2].After.Heading != target {
				t.Fatalf("frame 30 heading %v -> %v, want 1 -> %v", rec.Poses[2].Before.Heading, rec.Poses[2].After.Heading, target)
			}
			// 历史查询与当前位姿都反映实际校正结果。
			for _, tm := range []int64{10, 30} {
				p, err := m.PoseAt(tm)
				if err != nil {
					t.Fatalf("PoseAt(%d): %v", tm, err)
				}
				if p.Heading != target {
					t.Fatalf("PoseAt(%d) heading = %v, want %v", tm, p.Heading, target)
				}
			}
			if p, _ := m.PoseAt(20); p.Heading != want20 {
				t.Fatalf("PoseAt(20) heading = %v, want %v", p.Heading, want20)
			}
			if cur, _ := m.CurrentPose(); cur.Heading != target {
				t.Fatalf("current heading = %v, want %v", cur.Heading, target)
			}
			// 路标观测按保留的小朝向转换：正前方 1 米的路标地图纵坐标保留
			// 与目标同号的非零分量（sin(±1e-20) 在 float64 中即 ±1e-20）。
			if len(rec.Landmarks) != 1 || rec.Landmarks[0].ID != "L" {
				t.Fatalf("landmark changes = %+v", rec.Landmarks)
			}
			if la := rec.Landmarks[0].After; la.X != 1 || la.Y != target {
				t.Fatalf("landmark after = (%v,%v), want (1,%v)", la.X, la.Y, target)
			}
			lms, err := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
			if err != nil {
				t.Fatal(err)
			}
			if len(lms) != 1 || lms[0].X != 1 || lms[0].Y != target {
				t.Fatalf("landmarks = %+v, want (1,%v)", lms, target)
			}
			// 校正后的末帧带有小朝向：随后导入的前进运动按它定位，留下同
			// 号的横向分量，而不是重新按零朝向定位。
			res, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
				{Time: 40, DX: 1, DHeading: 0},
			}})
			if err != nil {
				t.Fatalf("ImportSegment after correction: %v", err)
			}
			if res.EndPose.Heading != target || res.EndPose.X != 1 || res.EndPose.Y != target {
				t.Fatalf("end pose = (%v,%v,%v), want (1,%v,%v)",
					res.EndPose.X, res.EndPose.Y, res.EndPose.Heading, target, target)
			}

			// 重开后当前位姿、历史查询、路标与校正记录保持一致。
			path := m.Path()
			if err := m.Close(); err != nil {
				t.Fatal(err)
			}
			m2, err := Open(path)
			if err != nil {
				t.Fatalf("Open: %v", err)
			}
			defer m2.Close()
			if cur, _ := m2.CurrentPose(); cur.Heading != target || cur.X != 1 || cur.Y != target {
				t.Fatalf("after reopen current pose = %+v, want (1,%v,%v)", cur, target, target)
			}
			if p, _ := m2.PoseAt(10); p.Heading != target {
				t.Fatalf("after reopen PoseAt(10) heading = %v, want %v", p.Heading, target)
			}
			lms, _ = m2.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
			if len(lms) != 1 || lms[0].X != 1 || lms[0].Y != target {
				t.Fatalf("after reopen landmark = %+v, want (1,%v)", lms, target)
			}
			recs, err := m2.Corrections()
			if err != nil {
				t.Fatal(err)
			}
			if len(recs) != 1 || len(recs[0].Poses) != 3 ||
				recs[0].Poses[0].After.Heading != target ||
				recs[0].Poses[2].After.Heading != target {
				t.Fatalf("after reopen correction record = %+v", recs)
			}
		})
	}
}

// 跨越 ±π 边界的校正仍表示同一个物理方向：锚点朝向在 +π 附近，目标再向
// 正方向越过 +π，结果归一为 -π 一侧的等价角度，锚点位置不变。
func TestTinyHeadingCorrectionAcrossPiBoundary(t *testing.T) {
	m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
	anchorHeading := normalizeAngle(math.Pi - 1e-15) // +π 内侧一个可表示的小角
	if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
		{Time: 10, DHeading: anchorHeading},
	}}); err != nil {
		t.Fatalf("ImportSegment: %v", err)
	}
	// 目标朝向沿正方向再转 3e-15，物理上越过 +π；提交值本身在范围外，
	// 由校正归一。
	targetHeading := anchorHeading + 3e-15
	rec, err := m.Correct(Correction{
		ID:     "c",
		Anchor: 10,
		Target: CorrectionTarget{X: 0, Y: 0, Heading: targetHeading, Variance: 0},
	})
	if err != nil {
		t.Fatalf("Correct: %v", err)
	}
	dHeading := normalizeAngle(normalizeAngle(targetHeading) - anchorHeading)
	want := normalizeAngle(anchorHeading + dHeading)
	if want >= 0 {
		t.Fatalf("test setup: expected wrap to the -pi side, got %v", want)
	}
	if rec.Poses[0].After.Heading != want {
		t.Fatalf("corrected heading = %v, want boundary-folded %v", rec.Poses[0].After.Heading, want)
	}
	if rec.Poses[0].After.X != 0 || rec.Poses[0].After.Y != 0 {
		t.Fatalf("anchor position changed: (%v,%v)", rec.Poses[0].After.X, rec.Poses[0].After.Y)
	}
	// 正 π 始终表示为负 π。
	if h := rec.Poses[0].After.Heading; h >= math.Pi || h < -math.Pi {
		t.Fatalf("heading %v outside [-pi, pi)", h)
	}
}

// Package posemap 是本地定位与地图的本地基线，提供可由本地程序调用的
// 二维轨迹与路标功能：创建地图、按段导入有序帧、查询历史位姿与矩形区域
// 内的路标，并把全部数据持久化到本地文件，关闭后重新打开结果一致。
package posemap

import (
	"errors"
	"math"
	"strconv"
)

// Config 描述创建一份新地图时的初始状态与两个阈值。
//
// 位置单位为米，时间单位为整数毫秒，朝向单位为弧度。初始位置方差
// InitialVariance 必须非负；最大帧间隔 MaxInterval（毫秒）与路标合并
// 距离 MergeDistance（米）必须为正。
type Config struct {
	InitialTime     int64   // 初始时间（毫秒）
	InitialX        float64 // 初始位置 X（米，地图坐标）
	InitialY        float64 // 初始位置 Y（米，地图坐标）
	InitialHeading  float64 // 初始朝向（弧度）
	InitialVariance float64 // 初始位置方差（非负）
	MaxInterval     int64   // 相邻位姿允许的最大时间间隔（毫秒，必须为正）
	MergeDistance   float64 // 路标观测合并距离（米，必须为正）
}

// Observation 是一帧中对单个路标的一次观测，位置在机器人自身坐标下。
type Observation struct {
	ID string  // 路标标识，非空
	X  float64 // 自身坐标下的 X（米）
	Y  float64 // 自身坐标下的 Y（米）
}

// Frame 是一段有序轨迹中的一帧：时间、自身坐标下的平移、朝向增量、
// 非负运动方差以及零个或多个路标观测。
type Frame struct {
	Time         int64         // 帧时间（毫秒）
	DX           float64       // 自身坐标下平移 X（米）
	DY           float64       // 自身坐标下平移 Y（米）
	DHeading     float64       // 朝向增量（弧度）
	MoveVariance float64       // 运动方差（非负）
	Observations []Observation // 零个或多个路标观测，同帧按输入次序处理
}

// Segment 是一批带有非空段标识的有序帧。
type Segment struct {
	ID     string  // 段标识，非空
	Frames []Frame // 有序帧
}

// Pose 是一份二维位姿及其位置方差。
type Pose struct {
	Time     int64
	X        float64
	Y        float64
	Heading  float64
	Variance float64
}

// Landmark 是地图坐标下的一个路标及其被接受的观测次数。
type Landmark struct {
	ID    string
	X     float64
	Y     float64
	Count int
}

// Invalidation 是一次路标失效操作：非空操作标识、非空原因与一组非空、
// 不重复的路标标识。提交时这些路标的当前有效记录同时失效，失效时间取
// 提交时的当前位姿时间。
type Invalidation struct {
	ID        string   // 操作标识，非空
	Reason    string   // 失效原因，非空
	Landmarks []string // 路标标识，非空且不重复
}

// InvalidationResult 是一次成功失效操作的结果：失效时间（提交时的当前
// 位姿时间）以及每个被撤下路标的标识与其失效的出现编号。
type InvalidationResult struct {
	Time      int64
	Landmarks []InvalidatedLandmark
}

// InvalidatedLandmark 记录一个被撤下路标的标识与被失效记录的出现编号。
type InvalidatedLandmark struct {
	ID         string
	Occurrence int
}

// Appearance 是同一标识某一次出现的记录：出现编号（同一标识首次出现为
// 1，每次失效后再次出现递增）、位置、观测计数、是否仍为当前有效记录、
// 首次观测时间，以及失效时间与原因。仍有效（Active 为真）时失效时间与
// 原因没有意义；旧文件缺少逐帧来源时 HasFirstSeen 为假，首次观测时间
// 未知。
type Appearance struct {
	Number        int // 出现编号，从 1 开始
	Landmark      Landmark
	Active        bool  // 是否为当前有效记录
	FirstSeenTime int64 // 首次观测所在帧的时间
	HasFirstSeen  bool  // 旧文件缺少逐帧来源时为假，表示首次观测时间未知
	InvalidTime   int64 // 失效时间（提交失效时的当前位姿时间）
	InvalidReason string
	InvalidOpID   string
}

// LandmarkHistory 是同一标识按出现编号递增排列的全部出现记录。
type LandmarkHistory struct {
	ID          string
	Appearances []Appearance
}

// CorrectionTarget 是已确认回环提交的目标：某个已保存帧应有的位姿与
// 非负位置方差。位置单位为米，朝向单位为弧度。
type CorrectionTarget struct {
	X        float64
	Y        float64
	Heading  float64
	Variance float64
}

// Correction 是一次已确认回环校正请求：非空标识、必须命中已导入帧的
// 锚点时间，以及该帧应有的位姿与非负位置方差。
type Correction struct {
	ID     string           // 校正标识，非空
	Anchor int64            // 已保存帧的准确时间（毫秒）
	Target CorrectionTarget // 锚点帧应有的位姿与方差
}

// PoseChange 是一帧位姿的校正前后值。
type PoseChange struct {
	Before Pose
	After  Pose
}

// LandmarkChange 是一个路标某一次出现的校正前后值（观测次数不变）。
// Occurrence 给出受影响的出现编号；同一标识的不同出现分别记录。
type LandmarkChange struct {
	ID         string
	Occurrence int
	Before     Landmark
	After      Landmark
}

// CorrectionRecord 是一次成功校正按提交次序保留的记录。后续校正可
// 覆盖相同时间范围，但先前记录永不被改写。
type CorrectionRecord struct {
	ID        string           // 校正标识
	Anchor    int64            // 锚点帧时间
	Target    CorrectionTarget // 提交目标
	EndTime   int64            // 受影响末帧时间（提交时的末帧）
	Poses     []PoseChange     // 受影响位姿的校正前后值，按时间升序
	Landmarks []LandmarkChange // 受影响路标出现的校正前后值，按标识再按出现编号升序
}

// RejectError 表示一次段导入、路标失效或回环校正因语义不合法而被整体
// 拒绝。
//
// Kind 为可区分的拒绝原因（见 Reject* 常量）；当原因涉及具体帧时，
// Frame 给出从零开始的帧序号且 HasFrame 为真；路标冲突时 Landmark
// 给出涉及的路标标识；重复段内容冲突时 Landmark 给出冲突的段标识。
// 两种情况下 HasLandmark 均为真。校正类原因用 Time 给出提交的锚点
// 时间且 HasTime 为真；校正中路标冲突时 Time 改为给出冲突观测所在帧的
// 时间、Landmark 给出路标标识、Occurrence 给出冲突的出现编号（1 起），
// HasLandmark 与 HasOccurrence 均为真。校正中某条观测转换到地图坐标后
// 出现非有限数值时同样处理：Time 为该观测所在帧的实际时间、Landmark
// 与 Occurrence 指出路标标识及其所属的出现编号。失效操作中找不到路标
// 或路标当前已失效时，Landmark 给出路标标识。
type RejectError struct {
	Kind          string
	Frame         int
	HasFrame      bool
	Landmark      string
	HasLandmark   bool
	Time          int64
	HasTime       bool
	Occurrence    int
	HasOccurrence bool
}

func (e *RejectError) Error() string {
	switch e.Kind {
	case RejectEmptySegment:
		return "posemap: segment has no frames"
	case RejectEmptyID:
		if e.HasFrame {
			return "posemap: frame " + strconv.Itoa(e.Frame) + " has empty landmark id"
		}
		return "posemap: empty segment, correction or invalidation id"
	case RejectEmptyReason:
		return "posemap: invalidation reason is empty"
	case RejectEmptyLandmarkList:
		return "posemap: invalidation landmark list is empty"
	case RejectDuplicateLandmarkEntry:
		return "posemap: invalidation lists landmark " + e.Landmark + " more than once"
	case RejectLandmarkNotFound:
		return "posemap: landmark " + e.Landmark + " not found"
	case RejectLandmarkInactive:
		return "posemap: landmark " + e.Landmark + " has no active occurrence"
	case RejectInvalidationMismatch:
		return "posemap: invalidation id " + e.Landmark + " already saved with different content"
	case RejectNegativeVariance:
		if e.HasTime {
			return "posemap: correction target variance is negative"
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " has negative motion variance"
	case RejectNonFinite:
		if e.HasTime {
			if e.HasLandmark {
				if e.HasOccurrence {
					return "posemap: correction makes observation of landmark " + e.Landmark + " occurrence " + strconv.Itoa(e.Occurrence) + " at frame time " + strconv.FormatInt(e.Time, 10) + " non-finite"
				}
				return "posemap: correction makes observation of landmark " + e.Landmark + " at frame time " + strconv.FormatInt(e.Time, 10) + " non-finite"
			}
			return "posemap: correction target or corrected result has non-finite value"
		}
		if e.HasLandmark {
			return "posemap: frame " + strconv.Itoa(e.Frame) + " has non-finite observation of landmark " + e.Landmark
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " has non-finite value"
	case RejectTimeOrder:
		if e.Frame == 0 {
			return "posemap: first frame must be later than initial time or previous segment end"
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " time is not strictly increasing"
	case RejectInterval:
		return "posemap: frame " + strconv.Itoa(e.Frame) + " exceeds the maximum time interval"
	case RejectLandmarkConflict:
		if e.HasTime {
			if e.HasOccurrence {
				return "posemap: correction conflicts landmark " + e.Landmark + " occurrence " + strconv.Itoa(e.Occurrence) + " at frame time " + strconv.FormatInt(e.Time, 10)
			}
			return "posemap: correction conflicts landmark " + e.Landmark + " at frame time " + strconv.FormatInt(e.Time, 10)
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " observation of landmark " + e.Landmark + " is beyond merge distance"
	case RejectDuplicateMismatch:
		return "posemap: segment id " + e.Landmark + " already saved with different content"
	case RejectAnchorNotFound:
		return "posemap: anchor time " + strconv.FormatInt(e.Time, 10) + " does not match an imported frame"
	case RejectCorrectionMismatch:
		return "posemap: correction id " + e.Landmark + " already saved with different content"
	case RejectNoBasis:
		return "posemap: correction range from " + strconv.FormatInt(e.Time, 10) + " lacks per-frame observation sources"
	default:
		return "posemap: request rejected (" + e.Kind + ")"
	}
}

// 可区分的拒绝原因。
const (
	RejectEmptySegment           = "empty_segment"            // 空批次
	RejectEmptyID                = "empty_id"                 // 空段/路标/校正/失效标识
	RejectEmptyReason            = "empty_reason"             // 失效原因为空
	RejectEmptyLandmarkList      = "empty_landmark_list"      // 失效路标列表为空
	RejectDuplicateLandmarkEntry = "duplicate_landmark_entry" // 失效列表中路标重复
	RejectLandmarkNotFound       = "landmark_not_found"       // 失效的路标从未出现
	RejectLandmarkInactive       = "landmark_inactive"        // 失效的路标当前无有效记录
	RejectInvalidationMismatch   = "invalidation_mismatch"    // 同一失效标识对应不同内容
	RejectNegativeVariance       = "negative_variance"        // 负运动方差或负目标方差
	RejectNonFinite              = "non_finite"               // 非有限数值（NaN/Inf）
	RejectTimeOrder              = "time_order"               // 时间未严格递增或首帧不够晚
	RejectInterval               = "interval_exceeded"        // 相邻位姿间隔超过上限
	RejectLandmarkConflict       = "landmark_conflict"        // 同标识路标超出合并距离
	RejectDuplicateMismatch      = "duplicate_mismatch"       // 同一段标识对应不同内容
	RejectAnchorNotFound         = "anchor_not_found"         // 校正锚点未命中已导入帧
	RejectCorrectionMismatch     = "correction_mismatch"      // 同一校正标识对应不同内容
	RejectNoBasis                = "no_basis"                 // 旧地图缺少逐帧观测来源
)

// 哨兵错误，供 errors.Is 使用。
var (
	// ErrClosed 在已关闭的地图上操作时返回。
	ErrClosed = errors.New("posemap: map is closed")
	// ErrInvalidConfig 在创建地图的配置不合法时返回。
	ErrInvalidConfig = errors.New("posemap: invalid config")
	// ErrInvalidRect 在矩形查询的上下界颠倒时返回。
	ErrInvalidRect = errors.New("posemap: invalid rectangle")
	// ErrNotFound 在查询时间早于初始时间（无任何不晚于它的位姿）时返回。
	ErrNotFound = errors.New("posemap: pose not found")
	// ErrLandmarkNotFound 在按标识查询路标历次出现而该标识从未出现时返回。
	ErrLandmarkNotFound = errors.New("posemap: landmark not found")
	// ErrCorrupt 在数据文件损坏、截断或校验失败时返回。
	ErrCorrupt = errors.New("posemap: corrupt data file")
	// ErrUnsupportedVersion 在数据文件格式版本不受支持时返回。
	ErrUnsupportedVersion = errors.New("posemap: unsupported file format version")
)

// normalizeAngle 把任意角度归一到 [-π, π)。
//
// 已经落在范围内的角度原样返回（零保持零，-π 保持 -π，已经可表示的微小
// 角度也不被当舍入误差丢掉）；只有范围外的角度才按整圈 2π 平移回范围。
// 不能先把角度加上或减去 π 再对所有输入统一取模——例如 1e-16 加 π 后低位
// 被 π 的精度吞掉，再减回 π 时微小转角就变成了零，连续多帧的小转向因此
// 无法累积。
func normalizeAngle(a float64) float64 {
	if a == 0 {
		return 0 // 零保持零，-0 也规范成 +0。
	}
	if -math.Pi <= a && a < math.Pi {
		return a
	}
	// 范围外（含 +π）：平移整圈到 [-π, π)。a 有限且 |a| 可能远大于 2π，
	// math.Mod 的结果落在 (-2π, 2π)，至多再平移一次即入范围；a 为非有限
	// 值时结果为 NaN，由调用方按非有限拒绝。
	a = math.Mod(a+math.Pi, 2*math.Pi)
	if a < 0 {
		a += 2 * math.Pi
	}
	a -= math.Pi
	// 浮点取模在边界上可能恰好落到 +π（例如输入 -π 再小一个最小可表示
	// 转角），+π 不属于 [-π,π)，折回 -π：二者物理方向完全相同。
	if a >= math.Pi {
		a -= 2 * math.Pi
	}
	return a
}

// isFinite 判断数值既不是 NaN 也不是 Inf。
func isFinite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }

// mergeMean 把一个新样本 v 并入既有等权均值（已有 count 个样本），
// 返回 count+1 个样本的均值。与 (mean*count + v)/(count+1) 数学等价，
// 但按 mean + (v-mean)/(count+1) 计算：大数值坐标下 mean*count 会溢出
// 为无穷，而这里每一步都只是有限值之间的凸组合，结果保持有限且落在
// 参与平均的坐标范围内。调用方须保证 v 与 mean 均为有限值且二者之差
// 有限（被接受的观测与当前均值相距不超过有限的合并距离，自然满足）。
func mergeMean(mean, v float64, count int) float64 {
	return mean + (v-mean)/float64(count+1)
}

// localToMap 把机器人自身坐标下的点 (lx, ly) 按给定地图坐标位姿
// 转换到地图坐标：旋转 heading 后平移。
func localToMap(px, py, heading, lx, ly float64) (float64, float64) {
	c, s := math.Cos(heading), math.Sin(heading)
	return px + c*lx - s*ly, py + s*lx + c*ly
}

package posemap

import "math"

// aggregate.go 承载“同一路标一次出现的观测接纳与合并规则”这一公共业务，
// 供轨迹导入（ImportSegment）与回环校正重放（Correct）共同使用，保证两条
// 流程对同一种观测的转换、接纳、等权平均与计数规则始终一致：
//
//   - 观测先由机器人自身坐标按当时位姿转换到地图坐标（localToMap）；
//   - 转换结果出现非有限数值时，优先按数值异常处理，不降级为距离冲突，
//     也不留到保存时才报普通错误；
//   - 该次出现的第一条观测直接作为平均位置起点、计数 1，不做距离判断；
//   - 其后每条观测与当时的平均位置比较，距离恰好等于合并上限仍可接纳，
//     超过上限则拒绝（且整条操作随之整体拒绝）；
//   - 接纳后位置是全部已接受观测的等权平均，按 mergeMean 增量计算以避免
//     大坐标下 mean*count 溢出，计数按实际接纳次数加一；
//   - 同帧多条观测按输入次序逐条处理，前一条接纳后的平均位置会影响下一
//     条的距离判断，不能先汇总整帧再统一判断。
//
// 聚合器只持有规则本身关心的计数与位置；出现编号、有效状态、失效信息、
// 首次观测时间等仍由各自流程在聚合器之外维护，规则不改变它们。

// obsRejectReason 区分一次观测被拒绝的原因。
type obsRejectReason int

const (
	obsAccepted  obsRejectReason = iota // 接纳（含首次建点）
	obsNonFinite                        // 转换到地图坐标后为非有限数值
	obsConflict                         // 与当时平均位置的距离超过合并上限
)

// observationAgg 是同一路标某一次出现对已接纳观测的增量聚合：等权平均
// 位置 (x,y) 与已接纳条数 count。count 为 0 时该次出现尚未接纳任何观测，
// 此时 (x,y) 无意义，第一条观测只做有限性检查即直接建点。
//
// 两种流程会在重放本段观测之前，先以一组“不在本次重放范围内、但固定有效”
// 的已接受观测作为起点（seed）：
//
//   - 导入时并入一条已有有效出现：该出现此前已提交的观测是固定历史，本段
//     新观测在其当前均值上增量合并；
//   - 回环校正重放旧文件第 1 次出现：旧文件缺少逐帧来源的观测无法重放，
//     其贡献固定为文件中的聚合值（legacyCount 次平均），依据完整的观测再
//     做增量平均。
//
// 起点本身不做距离检查（这些观测此前已按同一规则接纳），只有之后纳入的
// 观测才与（含固定起点在内的）当时平均位置比较。
type observationAgg struct {
	count int
	x     float64
	y     float64
}

// seed 以一组固定的已接受观测（count 条、等权平均 (x,y)）作为聚合起点。
// 调用时聚合器必须为空（尚未接纳任何观测）。
func (a *observationAgg) seed(count int, x, y float64) {
	a.count = count
	a.x = x
	a.y = y
}

// admit 按统一规则接纳一条观测：pose 为该观测所在帧运动完成后（导入）或
// 校正后（回环重放）的地图坐标位姿，ob 为机器人自身坐标下的观测，
// mergeDistance 为合并上限。
//
// 返回 obsAccepted 表示已并入等权平均（或作为第一条观测建点）；否则返回
// obsNonFinite（转换结果非有限，优先于距离冲突）或 obsConflict（距离严格
// 超过上限；恰好等于上限仍接纳）。被拒绝时聚合状态保持不变。
func (a *observationAgg) admit(pose Pose, ob Observation, mergeDistance float64) obsRejectReason {
	mx, my := localToMap(pose.X, pose.Y, pose.Heading, ob.X, ob.Y)
	// 位姿/观测坐标过大时转换可能溢出为 NaN/无穷：无论这是该次出现的
	// 第一条观测还是与既有平均合并，数值异常都优先于距离冲突。
	if !isFinite(mx) || !isFinite(my) {
		return obsNonFinite
	}
	if a.count > 0 {
		// 与当时平均位置比较：恰好等于合并上限仍可接纳，严格超过才拒绝。
		// 被接受观测与均值相距不超过有限的合并上限，二者之差有限，Hypot 不会溢出。
		if math.Hypot(mx-a.x, my-a.y) > mergeDistance {
			return obsConflict
		}
		a.x = mergeMean(a.x, mx, a.count)
		a.y = mergeMean(a.y, my, a.count)
	} else {
		// 首次出现（或该次出现重放到的第一条观测）：从一次观测开始，
		// 平均位置即观测位置、计数 1，不做距离判断。
		a.x, a.y = mx, my
	}
	a.count++
	return obsAccepted
}

