package main

import (
	"fmt"
	"math"
)

func main() {
	tau := 2 * math.Pi
	eps := 6.283185307179587 - tau
	fmt.Printf("tau          = %.20g\n", tau)
	fmt.Printf("input        = %.20g\n", 6.283185307179587)
	fmt.Printf("input - tau  = %.20g\n", eps)

	for _, a := range []float64{tau + eps, tau - eps, 6.283185307179587, tau, -tau, -tau - eps, -tau + eps} {
		r := math.Mod(a+math.Pi, tau)
		fmt.Printf("\na = %.20g\n  a+pi = %.20g\n  mod  = %.20g\n", a, a+math.Pi, r)
		if r < 0 {
			r += tau
		}
		r -= math.Pi
		if r >= math.Pi {
			r -= tau
		}
		fmt.Printf("  norm = %.20g\n", r)
	}
}
EOF
