cat > /tmp/check_new.go <<'EOF'
package main

import (
	"fmt"
	"math"
)

func newNorm(a float64) float64 {
	if a == 0 {
		return 0
	}
	if -math.Pi <= a && a < math.Pi {
		return a
	}
	r := math.Mod(a, 2*math.Pi)
	if r >= math.Pi {
		r -= 2 * math.Pi
	} else if r < -math.Pi {
		r += 2 * math.Pi
	}
	if r == 0 {
		return 0
	}
	return r
}

func main() {
	tau := 2 * math.Pi
	eps := 6.283185307179587 - tau
	fmt.Printf("eps = %.20g\n\n", eps)
	cases := []struct{ name string; in, want float64 }{
		{"two pi + eps (task input)", tau + eps, eps},
		{"literal 6.283185307179587", 6.283185307179587, eps},
		{"two pi - eps", tau - eps, -eps},
		{"two pi exact", tau, 0},
		{"minus two pi exact", -tau, 0},
		{"minus two pi - eps", -tau - eps, -eps},
		{"minus two pi + eps", -tau + eps, eps},
		{"tiny+", 1e-16, 1e-16},
		{"tiny-", -1e-16, -1e-16},
		{"zero", 0, 0},
		{"+pi", math.Pi, -math.Pi},
		{"-pi", -math.Pi, -math.Pi},
		{"pi/2+3pi", math.Pi/2 + 3*math.Pi, -math.Pi / 2},
		{"3pi", 3 * math.Pi, -math.Pi},
		{"-3pi", -3 * math.Pi, -math.Pi},
		{"-4.0", -4.0, -4.0 + tau},
		{"4.0", 4.0, 4.0 - tau},
		{"100.5 turns", 201*math.Pi + 0.25, func() float64 { r := math.Mod(201*math.Pi+0.25, tau); if r >= math.Pi { r -= tau }; return r }()},
	}
	bad := 0
	for _, c := range cases {
		got := newNorm(c.in)
		ok := got == c.want && got >= -math.Pi && got < math.Pi
		if !ok { bad++ }
		fmt.Printf("%-28s in=% .18g got=% .18g want=% .18g  %v\n", c.name, c.in, got, c.want, ok)
	}
	// huge inputs: result must stay finite and within range (remainder defined on rounded operand)
	for _, a := range []float64{1e308, -1e308, 1e16, -1e16} {
		got := newNorm(a)
		ok := isFinite(got) && got >= -math.Pi && got < math.Pi
		if !ok { bad++ }
		fmt.Printf("%-28s in=% .8g got=% .18g inRange=%v\n", "huge", a, got, ok)
	}
	// non-finite stays NaN
	if g := newNorm(math.NaN()); !math.IsNaN(g) { bad++; fmt.Println("NaN wrong") }
	if g := newNorm(math.Inf(1)); !math.IsNaN(g) { bad++; fmt.Println("+Inf wrong") }
	if g := newNorm(math.Inf(-1)); !math.IsNaN(g) { bad++; fmt.Println("-Inf wrong") }
	fmt.Printf("\nbad = %d\n", bad)
}

func isFinite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }
EOF
