// normalizeAngle 把任意角度归一到 [-π, π)。
//
// 已经落在范围内的角度原样返回（零保持零，-π 保持 -π，已经可表示的微小
// 角度也不被当舍入误差丢掉）；范围外的角度只在其自身量级上减去整数个
// 整圈——直接对输入做 math.Mod(a, 2π) 并向区间平移。绝不能先把角度加上
// 或减去 π 再取模：在整圈附近 a+π 落在 3π 量级（ULP 约 8.88e-16），整圈
// 上方/下方一个可表示余量（如 6.283185307179587 = 2π + 8.88e-16，或
// 2π - 8.88e-16）在相加时就被该量级的精度吞掉，取模后恰好得到 π、再折回
// 零，连续多帧的小转向因此无法累积；先加 π 只在 0 附近（a+π 在 π 量级，
// ULP 4.44e-16）侥幸成立，覆盖不了整圈附近同样真实的有符号余量。
func normalizeAngle(a float64) float64 {
	if a == 0 {
		return 0 // 零保持零，-0 也规范成 +0。
	}
	if -math.Pi <= a && a < math.Pi {
		return a
	}
	// 范围外：直接在输入自身量级上对整圈取余（math.Mod 按向零取整，余数
	// 与输入同号且 |余数| < 2π），不预先平移到更高 ULP 的量级；余量因此
	// 在它实际出现的量级（0 附近）上保留下来。余数落在 (-2π,-π] 或
	// [π,2π) 时再向中间平移一次即入 [-π,π)。a 为非有限值时余数为 NaN，
	// 由调用方按非有限拒绝。
	a = math.Mod(a, 2*math.Pi)
	if a >= math.Pi {
		a -= 2 * math.Pi
	} else if a < -math.Pi {
		a += 2 * math.Pi
	}
	if a == 0 {
		return 0 // 恰好整数圈（±2π、±4π……）得到 +0；-0 统一成 +0。
	}
	return a
}

