package posemap

import (
	"encoding/binary"
	"errors"
	"hash/crc32"
	"math"
	"os"
	"path/filepath"
	"testing"
)

func approxEq(t *testing.T, name string, got, want float64) {
	t.Helper()
	if math.IsNaN(want) {
		if !math.IsNaN(got) {
			t.Fatalf("%s = %v, want NaN", name, got)
		}
		return
	}
	if math.Abs(got-want) > 1e-10 {
		t.Fatalf("%s = %v, want %v", name, got, want)
	}
}

func baseConfig() Config {
	return Config{
		InitialTime:     0,
		InitialX:        1,
		InitialY:        2,
		InitialHeading:  0,
		InitialVariance: 0.5,
		MaxInterval:     1000,
		MergeDistance:   1.0,
	}
}

func newMap(t *testing.T, cfg Config) *Map {
	t.Helper()
	m, err := Create(filepath.Join(t.TempDir(), "map.pose"), cfg)
	if err != nil {
		t.Fatalf("Create: %v", err)
	}
	t.Cleanup(func() { _ = m.Close() })
	return m
}

func TestInvalidConfig(t *testing.T) {
	dir := t.TempDir()
	cases := []Config{
		baseConfig(),
	}
	{
		c := baseConfig()
		c.MaxInterval = 0
		cases = append(cases, c)
	}
	{
		c := baseConfig()
		c.MaxInterval = -1

